import{_ as a,o as t,c as r,a2 as i}from"./chunks/framework.DU2spEDf.js";const h=JSON.parse('{"title":"Overview","description":"","frontmatter":{},"headers":[],"relativePath":"overview.md","filePath":"overview.md","lastUpdated":1787906606000}'),o={name:"overview.md"};function s(n,e,l,d,c,p){return t(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h1><p><strong>Product:</strong> Ishuko — Maize grading and selling platform</p><h2 id="what-ishuko-does" tabindex="-1">What Ishuko Does <a class="header-anchor" href="#what-ishuko-does" aria-label="Permalink to &quot;What Ishuko Does&quot;">​</a></h2><p>Ishuko is an agri-tech mobile app that bridges the gap between the cooperatives that sell maize produce and wholesale buyers that need this maize product. The mobile app allows cooperatives to obtain quality assessment grades for their maize produce by taking maize images via the app. The app uses Computer Vision AI to grade the maize into one of four categories:</p><ul><li><strong>Grade A</strong> — Excellent</li><li><strong>Grade B</strong> — Good</li><li><strong>Grade C</strong> — Average</li><li><strong>Grade D</strong> — Poor</li></ul><p>A Quality Assessment Report is generated on the platform that the cooperative can use to market their produce to buyers on the integrated marketplace. Buyers can place orders and pay for them via the mobile app. The Ishuko mobile app is built using the Flutter framework.</p><h2 id="problem-statement" tabindex="-1">Problem Statement <a class="header-anchor" href="#problem-statement" aria-label="Permalink to &quot;Problem Statement&quot;">​</a></h2><p>Despite digital platforms providing market access for smallholder farmers in Zambia, smallholder farmers still have limited access to market and buyers due to poor quality produce, leading to exploitation by middlemen. Commercial buyers remain highly reluctant to source directly from small scale farmers due to a critical lack of quality assurance.</p><h2 id="product-objectives" tabindex="-1">Product Objectives <a class="header-anchor" href="#product-objectives" aria-label="Permalink to &quot;Product Objectives&quot;">​</a></h2><p>The Ishuko mobile app aims to solve for:</p><ul><li><strong>Market access</strong> — smallholder farmers&#39; cooperatives face challenges accessing buyers willing to pay market price, solved by automatically allocating market price based on the assigned grade.</li><li><strong>Subjective grading</strong> — traditional crop grading relies on manual visual inspection by farmers or experts, which can lead to arbitrary downgrading and low pricing. This is addressed by an AI grading system that assigns a grade based on an image.</li><li><strong>Cooperative invisibility</strong> — lack of verification and trust is addressed through an AI-generated quality assurance grade.</li></ul><h2 id="intended-users" tabindex="-1">Intended Users <a class="header-anchor" href="#intended-users" aria-label="Permalink to &quot;Intended Users&quot;">​</a></h2><ol><li><strong>Cooperative Manager / Leader (Seller)</strong> — registers on the platform, logs harvest quantities, and uses the mobile camera to execute AI-driven quality grading sessions.</li><li><strong>Wholesale Buyer</strong> — a corporate entity seeking bulk volumes of maize via the platform&#39;s digital marketplace.</li></ol><h2 id="out-of-scope" tabindex="-1">Out of Scope <a class="header-anchor" href="#out-of-scope" aria-label="Permalink to &quot;Out of Scope&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Feature</th><th>Description</th></tr></thead><tbody><tr><td>Direct-to-Consumer Marketplace</td><td>Retail customers buying small quantities directly from farmers</td></tr><tr><td>Logistics Fleet Management</td><td>A transport network managing produce movement from farm → depot → buyer</td></tr></tbody></table><h2 id="assumptions" tabindex="-1">Assumptions <a class="header-anchor" href="#assumptions" aria-label="Permalink to &quot;Assumptions&quot;">​</a></h2><ul><li>A photographic sample captured by the cooperative leader is a statistically accurate representation of the entire aggregated batch, allowing the AI to assign a reliable grade.</li><li>Objective AI grading will bridge the trust gap with wholesalers, eliminating inspection delays and ensuring immediate payment to the cooperative.</li><li>Buyers will be willing to pay for produce in full before pickup.</li><li>Most cooperatives and buyers have and use mobile money options like Airtel and Zamtel.</li><li>The buyer can place a later date to pick up their produce.</li></ul><h2 id="dependencies" tabindex="-1">Dependencies <a class="header-anchor" href="#dependencies" aria-label="Permalink to &quot;Dependencies&quot;">​</a></h2><ul><li><strong>Airtel Africa Developer Portal (Airtel Money Zambia)</strong> — secure authentication handshakes and C2B/B2B/Transaction Refund API access</li><li><strong>Production SSL &amp; Routing Layer (HTTPS/TLS)</strong> — for asynchronous transaction confirmations and telecom webhooks</li><li><strong>Camera Hardware Bridge Module</strong> — locks image resolution parameters, blocks gallery uploads</li><li><strong>Image Compression Unit</strong> — compresses images to minimize data usage during transmission</li><li><strong>Cryptographic Token Library</strong> — generates single-use 6-digit codes</li><li><strong>YOLOv8 Framework</strong> — scans the image and outputs a grade</li><li><strong>OpenCV</strong> — handles preprocessing (spatial transforms, exposure normalization, contrast enhancement) before quality checking</li><li><strong>Live Market Data (UN WFP Humanitarian Data Exchange)</strong> — real-time pricing feed: <a href="https://data.humdata.org/dataset/wfp-food-prices-for-zambia" target="_blank" rel="noreferrer">wfp-food-prices-for-zambia</a></li></ul>',19)])])}const m=a(o,[["render",s]]);export{h as __pageData,m as default};
